class Object;

class PartitionFilter
{
public:
	virtual bool allow(Object *object) = 0;
	PartitionFilter *link(PartitionFilter *next);

	PartitionFilter *m_next;
};

// ?link@PartitionFilter@@QAEPAV1@PAV1@@Z
PartitionFilter *PartitionFilter::link(PartitionFilter *next)
{
	volatile PartitionFilter *cursor = 0;
	PartitionFilter *candidate = m_next;
	if (candidate != 0)
	{
		do
		{
			cursor = candidate;
			candidate = cursor->m_next;
		}
		while (candidate != 0);
		const_cast<PartitionFilter *>(cursor)->m_next = next;
	}
	else
	{
		m_next = next;
	}
	return this;
}
